// Generated by ktor-svelte. Do not edit.
export const themes = ['light','dark'] as const;

export type ThemeName = (typeof themes)[number];

export const defaultTheme: ThemeName = 'light';

function readCookie(): string | undefined {
    return document.cookie.match(/(?:^|; )ktor_svelte_theme=([^;]+)/)?.[1];
}

export function getTheme(): ThemeName {
    if (typeof document === 'undefined') return defaultTheme;
    const saved = readCookie();
    return themes.find((theme) => theme === saved) ?? defaultTheme;
}

export function setTheme(theme: ThemeName): void {
    document.documentElement.dataset.theme = theme;
    document.cookie = `ktor_svelte_theme=${theme}; path=/; max-age=31536000; samesite=lax`;
}
